    case 'create_payment_link': {
      const paymentAmount = this.num(args.amount);
      if (this.riskGate && paymentAmount > 0) {
        const gateDecision = this.riskGate.gatePaymentAction({
          amountCents: paymentAmount,
          reversible: true,
          target: 'lead',
